function LuaKLobbyClientEx:Awake()
    self.packetNameDict_   = {}
    self.packetHandlerMap_ = {}

    self.playerId_ = checkInt(GameUtils.GetPlayerId())
    ---@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if isNotNull(userComponent) then
        local HttpModule = CS.Engine.Http.HttpModule
        local serverDojo = userComponent:GetServerById(HttpModule.RequestBodyMeta.serverId)  
        local areaId = checkInt(serverDojo.areaId)
        if areaId > 0 then
            self.areaId = areaId
        end
    end

    -- create tcp client
    self.client              = CS.Engine.Network.TcpClient()
    self.client.onConnect    = Bind(self, self.OnTcpConnectHandler_)
    self.client.onDisconnect = Bind(self, self.OnTcpDisconnectHandler_)
    self.client.onError      = Bind(self, self.OnTcpErrorHandler_)
    self.client.onPing       = Bind(self, self.OnTcpPingHandler_)

    -- append update behavior
    local behaviorAction = CfUtils.BehaviourActionAdd(self.controller)
    behaviorAction.UpdateAction    = Bind(self, self.OnBehaviourUpdateHandler_)
    behaviorAction.OnDisableAction = Bind(self, self.OnBehaviourDisableHandler_)
    behaviorAction.OnDestroyAction = Bind(self, self.OnBehaviourDestoryHandler_)

    -- add event listen
    self.eventsDecorated_ = CfUtils.EventsDecorated({
        [Constants.EventNames.ONAPPQUIT] = Bind(self, self.OnAppQuitHandler_),
    })

    -- init default value
    self:SetPingDelta(DEFAULT_PING_DELTA)
    self:SetTimeoutDelta(DEFAULT_TIMEOUT_DELTA)
    self:SetRetryTimes(DEFAULT_RETRY_TIMES)
    self:SetWeakAnimeEnable(true)
end


function LuaKLobbyClientEx:Start()
end


function LuaKLobbyClientEx:OnDestroy()
    CfUtils.EventsUndecorated(self.eventsDecorated_)
    self:SwitchTcpWeakAnime_(false)

    self.onConnectCb    = nil
    self.onDisconnectCb = nil
    self.onTimeoutCb    = nil
    self.onStopCb       = nil
    self.onLogCb        = nil
    self.isDestroyed_   = true

    if isNotNull(self.client) then
        local tcpProtocolType = self.client.protocol:GetType()
        if isNotNull(tcpProtocolType:GetProperty("OnSendLog")) then
            self.client.protocol.OnSendLog = nil
        end
        if isNotNull(tcpProtocolType:GetProperty("OnTakeLog")) then
            self.client.protocol.OnTakeLog = nil
        end
        if isNotNull(tcpProtocolType:GetProperty("OnInfoLog")) then
            self.client.protocol.OnInfoLog = nil
        end

        self.client.packetHandlers:Clear()
        self.client.onConnect    = nil
        self.client.onDisconnect = nil
        self.client.onError      = nil
        self.client.onPing       = nil

        if self.client.isConnected then
            self:Disconnect()
        end
    end
    self.client = nil

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end


