--- 是否开启TCP日志监听
---@param isOpen boolean
function LuaKLobbyClientEx:IsOpenLogListen(isOpen)
    if isNotNull(self.client) and isOpen then
        local tcpProtocolType = self.client.protocol:GetType()
        if isNotNull(tcpProtocolType:GetProperty("OnSendLog")) then
            self.client.protocol.OnSendLog = function(packetId, packetMsg)
                self:TcpLog_(LOG_TYPE.SEND, packetMsg, packetId)
            end
        end
        if isNotNull(tcpProtocolType:GetProperty("OnTakeLog")) then
            self.client.protocol.OnTakeLog = function(packetId, packetMsg)
                self:TcpLog_(LOG_TYPE.TAKE, packetMsg, packetId)
            end
        end
        if isNotNull(tcpProtocolType:GetProperty("OnInfoLog")) then
            self.client.protocol.OnInfoLog = function(infoMsg)
                self:TcpLog_(LOG_TYPE.INFO, infoMsg)
            end
        end
    end
end


--- 设置 TCP消息处理回调
---@param packetId integer
---@param callback fun(packetId:integer, packetId:integer, packetData:table|string):void
function LuaKLobbyClientEx:SetPacketHandler(packetId, callback)
    -- save packet callback
    self.packetHandlerMap_[checkInt(packetId)] = callback

    if isNotNull(self.client) and self:IsPlaying() then
        ---@param packetId integer
        ---@param reader System.IO.BinaryReader
        ---@param bodyLen integer
        ---@param source System.Net.IPEndPoint
        self.client.packetHandlers[packetId] = function(packetId, reader, bodyLen, source)
            local jsonStr = KLobbyClientEx.ReadPayloadString(reader, bodyLen)
            if string.isEmpty(jsonStr) then return end

            local response = table.deserialize(jsonStr)
            local packetCb = self.packetHandlerMap_[checkInt(packetId)]
            if packetCb and response then
                packetCb(packetId, response or jsonStr)
            end
        end
    end
end


--- 连接 TCP通讯
--- 实例1 Connect("127.0.0.1:5127")
--- 实例2 Connect("127.0.0.1", 5127)
---@param host string @ IP地址，可以是域名，也可以是IP地址。
---@param port integer | nil @ 端口号，如果传入了域名，则端口号可以不传
function LuaKLobbyClientEx:Connect(host, port)
    self.connectHost_    = host
    self.connectPort_    = port
    self.isConnected_    = false
    self.isShuttingDown_ = false
    self.lastPingTime_   = KLobbyClientEx.clientTime

    -- 连接前必须调用 SetClientName 设置一个名字，不然长连接多了日志会混淆
    if not self.clientName_ then
        self:OnTcpErrorHandler_(string.fmt('# Must call :SetClientName(xxx)'))
        if self.onStopCb then self.onStopCb() end
        return
    end

    -- FIXME 重新注册消息回调（不知道为什么要清除再注册，原样移植过来）
    self.client.packetHandlers:Clear()
    for packetId, callback in pairs(self.packetHandlerMap_) do
        self:SetPacketHandler(packetId, callback)
    end

    -- 是否正在重连中
    if not self.client.isTryingToConnect then
        Application.runInBackground = true

        -- IPUtils.ResolveEndPoint 方法内做了单参数还是双参数的兼容处理
        -- 单参数就使用 : 冒号分隔端口和ip
        -- 双参数就直接使用端口和ip的传参
        local ipEndPoint = port ~= nil and IPUtils.ResolveEndPoint(host, port) or IPUtils.ResolveEndPoint(host)
        if isNull(ipEndPoint) then
            self:OnTcpErrorHandler_(string.fmt('# Unable to resolve [%1 %2]', host, port or ''))
            if self.onStopCb then self.onStopCb() end
        else
            self:Log(string.fmt('# Ready conenct [%1 %2]', host, port or ''))
            self.client:Connect(ipEndPoint, nil)
        end
    else
        self:Log('# Already connecting...')
    end
end


--- 重连 TCP通讯（基于上一次的连接地址，所以需要先调用过 Connect）
function LuaKLobbyClientEx:Reconnect()
    if self.connectHost_ == nil then
        self:OnTcpErrorHandler_(string.fmt('# Reconnect host invalid'))
        if self.onStopCb then self.onStopCb() end
        return
    end
    self.isReconnect_ = true
    self:ToMarkDisabled_()
    self:Connect(self.connectHost_, self.connectPort_)
end


--- 断开 TCP通讯
function LuaKLobbyClientEx:Disconnect()
    self:Log('# Manual disconnect...')

    if isNotNull(self.client) then
        self.client.packetHandlers:Clear()
    end

    self.isConnected_    = false
    self.isShuttingDown_ = true
    self:DoDisconnectNow_()
    self:DoDisconnect_()
end


--- 创建 TCP消息体，C#内部记录封装的消息体（分段发送的设计可用于对消息体二次加工，比如zip消息体）
---@param packetId integer
---@param data string | nil
---@return System.IO.BinaryWriter
function LuaKLobbyClientEx:BeginSend(packetId, data)
    self:TcpLog_(LOG_TYPE.SEND, data, packetId)
    return self.client:BeginSend(packetId, data)
end


--- 发送 TCP消息体，C#处理内部封装的消息体
---@param forced boolean | nil @ 是否立刻发送，默认false（这个参数看C#那边有 isActive 的判断，所以无论传入啥，其实都是立刻发送）
function LuaKLobbyClientEx:EndSend(isForced)
    if isNotNull(self.client) then
        self.client:EndSend(isForced)
    end
end


--- 发送 TCP消息，一步到位版
---@param packetId integer
---@param packetData table | string | nil
function LuaKLobbyClientEx:SendPacket(packetId, packetData)
    local sendMessage = packetData
    
    if sendMessage ~= nil then
        if type(sendMessage) == 'table' then
            -- 补充公参
            if not sendMessage.playerId then
                sendMessage.playerId = self.playerId_
            end
       
            if checkInt(self.areaId) > 0 then
                sendMessage.serverAreaId = self.areaId
            end

            -- 设置时间戳
            if not sendMessage.ts then
                sendMessage.ts = os.time()
            end
            sendMessage = table.serialize(sendMessage)
        else
            sendMessage = tostring(sendMessage)
        end
    end
    self:BeginSend(packetId, sendMessage)
    self:EndSend(false)
end


