function LuaKLobbyClientEx:ToMarkDisabled_()
    self.isConnected_    = false
    self.isShuttingDown_ = true
end


--- 尝试重连
function LuaKLobbyClientEx:DoRecontent_()
    -- 检测重试次数
    if self.retryTimesNow_ <= 0 then
        self:ToMarkDisabled_()

        -- 连接超时
        self:Log('# Timeout conenct')
        if self.onTimeoutCb then
            self.onTimeoutCb()
        end

    else
        -- 断开旧链接
        self:Disconnect()

        self.retryTimesNow_ = self.retryTimesNow_ - 1
        self:Log(string.fmt('# Retry conenct (%1/%2)', self.retryTimesNow_, self.retryTimesMax_))

        -- 重建新连接
        self:Reconnect()
    end
end


--- 处理TCP日志
---@param logType integer
---@param logBody string | table
---@param packetId integer | nil
function LuaKLobbyClientEx:TcpLog_(logType, logBody, packetId)
    local logMessage  = ''
    local socketName  = self.clientName_ or ''
    local socketIndex = self.client and checkInt(self.client.protocol.usedIndex) or '--'

    if logType == LOG_TYPE.SEND or logType == LOG_TYPE.TAKE then
        if IgnoreLogMap[checkInt(packetId)] then return end

        local packetName = tostring(CommonPacketNameMap[checkInt(packetId)] or self.packetNameDict_[checkInt(packetId)])
        local logTitle   = string.fmt('%1 %2', packetId, packetName)
        local logDetail  = ''
        if type(logBody) == 'table' then
            logDetail = table.toString(logBody, '')
        else
            logTitle = string.fmt('%1 : %2', logTitle, checkString(logBody))
        end

        if logType == LOG_TYPE.SEND then
            logMessage = string.fmt("<color=#3399CC>[%1_TCP_SEND:%2] %3</color>%4", socketName, socketIndex, logTitle, logDetail)
        else
            logMessage = string.fmt("<color=#99CC33>[%1_TCP_TAKE:%2] %3</color>%4", socketName, socketIndex, logTitle, logDetail)
        end
    else
        logMessage = string.fmt("<color=#CC9933>[%1_TCP_INFO:%2] %3</color>", socketName, socketIndex, logBody)
        logMessage = string.fmt('%1\n%2', logMessage, debug.traceback())
    end

    print(logMessage)
    if self.onLogCb then
        self.onLogCb(logMessage)
    end
end


---@param isShow boolean
function LuaKLobbyClientEx:SwitchTcpWeakAnime_(isShow)
    if not self.isWeakAnimEnable_ then return end
    CfUtils.SetSocketWeakAnim(isShow)
end


