-- handler

function LuaKLobbyClientEx:OnBehaviourUpdateHandler_()
    if self.connectHost_ == nil then return end

    -- 当前本机的毫秒数（它是以公历0001年1月1日00:00:00.000以来所经历的时间，不能用于直接用于时间转换）
    local clientTime = KLobbyClientEx.clientTime
    if self:IsActive() and (not self.isShuttingDown_) then

        -- 检测弱网提示
        if clientTime > (self.lastPingTime_ + self.weakDeltaTime_) then
            self:SwitchTcpWeakAnime_(true)
        end

        -- 检测连接超时
        if clientTime > (self.lastPingTime_ + self.timeoutDeltaTime_) then
            -- 更新检测时间点
            self.lastPingTime_ = clientTime
            self:DoRecontent_()
        end
    end

    self:ProcessPackets_()
end


function LuaKLobbyClientEx:OnBehaviourDestoryHandler_()
    -- FIXME 为什么关闭逻辑不写在 OnDestroyAction 中处理，而是放在 OnDisableAction 处理
    -- 不是很理解，虽然父级对象不会被 SetActive(false) 这样操作，书面理解上感觉存在隐患（现在也不敢动，沿用吧）
end


function LuaKLobbyClientEx:OnBehaviourDisableHandler_()
    self:ToMarkDisabled_()
end


--- TCP连接成功回调（其实是连接+验证成功，TCP握手成功 -> 发送1001进行验证 -> 收到1002登记成功 -> onConnect）
---@param success boolean
---@param message string
function LuaKLobbyClientEx:OnTcpConnectHandler_(success, message)
    self.isConnected_    = checkBool(success)
    self.isShuttingDown_ = false

    if self.isConnected_ then
        self:Log('# OnConnect verified')
        self:SwitchTcpWeakAnime_(false)

        local isReconnect   = self.isReconnect_
        self.lastPingTime_  = KLobbyClientEx.clientTime
        self.retryTimesNow_ = self.retryTimesMax_
        self.isReconnect_   = false

        if self.onConnectCb then
            self.onConnectCb(isReconnect)
        end

    else
        -- 触发在收到1000错误信息
        self:Log('# OnConnect fail : ' .. tostring(message))
        self:DoRecontent_()
    end
end


--- TCP断开连接回调（发生在收到2002断开连接，以及手动调用 DisconnectNow 的时候）
function LuaKLobbyClientEx:OnTcpDisconnectHandler_()
    self:Log('# OnDisconnect')
    self.isConnected_ = false

    if self.onDisconnectCb then
        self.onDisconnectCb()
    end
end


--- TCP连接错误回调（TcpClient.cs中只有在收到1000错误信息时才会触发，并且会调用 onConnect(false, err)）
---@param message string
function LuaKLobbyClientEx:OnTcpErrorHandler_(message)
    local errorMsg  = checkString(message)
    local errorData = table.deserialize(errorMsg)
    if errorData then
        errorMsg = checkString(errorData.msg)
    end
    self:ToMarkDisabled_()
    self:Log('# OnError : ' .. errorMsg)

    GameUtils.Toast(string.fmt("[Socket Error] _target_", { _target_ = errorMsg }), 3)
end


--- TCP心跳轮询回调
---@param source System.Net.IPEndPoint
---@param ping integer
function LuaKLobbyClientEx:OnTcpPingHandler_(source, ping)
    self.lastPingTime_ = KLobbyClientEx.clientTime
    self:SwitchTcpWeakAnime_(false)
end


function LuaKLobbyClientEx:OnAppQuitHandler_()
    self:ToMarkDisabled_()
    self:Log('# app quit')

    if isNotNull(self.controller) then
        CfUtils.SafeDelete(self.controller.gameObject, true)
    else
        self:OnDestroy()
    end
end


return LuaKLobbyClientEx
